  const notify=m=>{setToast(m);setTimeout(()=>setToast(""),1800)},closeArticle=()=>{setActive(article.remote?"文章管理":"草稿箱");notify(article.remote?"仓库文章请在文章管理中编辑":"文章已保存到当前浏览器草稿箱")};
